    """Convert 1 <= n <= 3999 to a Roman numeral using subtractive notation (IV, IX, XL, ...)."""
    val_to_roman = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    roman_num = []
    for val, sym in val_to_roman:
        while n >= val:
            roman_num.append(sym)
